use anyhow :: Context as _ ; use reqwest :: header :: HeaderMap ; use reqwest :: { Response , StatusCode , Url } ; # [doc = " Joins a base URL with a path, validating the path for security"] # [doc = ""] # [doc = " # Errors"] # [doc = ""] # [doc = " Returns an error if the path contains forbidden patterns or if URL parsing"] # [doc = " fails"] pub fn join_url (base_url : & str , path : & str) -> anyhow :: Result < Url > { if path . contains ("://") || path . contains ("..") { anyhow :: bail ! ("Invalid path: Contains forbidden patterns") ; } let path = path . trim_start_matches ('/') ; let url = Url :: parse (base_url) . with_context (| | format ! ("Failed to parse base URL: {base_url}")) ? . join (path) . with_context (| | format ! ("Failed to append {path} to base URL: {base_url}")) ? ; Ok (url) }